import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import yesman.epicfight.api.forgeevent.SkillBuildEvent;
import yesman.epicfight.skill.Skill;
import yesman.epicfight.skill.SkillBuilder;
import yesman.epicfight.skill.SkillCategories;
import yesman.epicfight.skill.SkillCategory;
import yesman.epicfight.world.capabilities.item.CapabilityItem;
import yesman.epicfight.world.capabilities.item.Style;
import yesman.epicfight.world.capabilities.item.WeaponCategory;

@Mod.EventBusSubscriber(modid="epicfightx", bus=Mod.EventBusSubscriber.Bus.MOD)
public class ExtraSkills {
    public static Skill ROLL;
    public static Skill STEP;
    public static Skill PICKAXE_SKILL;
    public static Skill SCYTHE_SKILL;
    public static Skill KATANA_SKILL;
    public static Skill KATANA_PASSIVE_SKILL;
    public static Skill GREATSWORD_DAGGER_SKILL;
    public static Skill GREAT_TACHI_SKILL;
    public static Skill COMBAT_MASTERY_I;
    public static Skill COMBAT_MASTERY_II;

    @SubscribeEvent
    public static void buildSkillEvent(SkillBuildEvent build) {
        SkillBuildEvent.ModRegistryWorker modRegistry = build.createRegistryWorker("epicfightx");
        ROLL = modRegistry.build("roll", EFXDodgeSkill::new, (SkillBuilder)EFXDodgeSkill.createEFXDodgeBuilder().setDefaultAnimations(AnimationsX.BIPED_ROLL_FORWARD, AnimationsX.BIPED_ROLL_BACKWARD, null, null, AnimationsX.BIPED_ROLL_BACKWARD).addAnimationsForWeapon((WeaponCategory)CapabilityItem.WeaponCategories.SPEAR, EFXStyles.SCYTHE, ExtraAnimations.SCYTHE_EVASIVE_STRIKE_F, ExtraAnimations.SCYTHE_EVASIVE_STRIKE_B, ExtraAnimations.SCYTHE_EVASIVE_STRIKE_L, ExtraAnimations.SCYTHE_EVASIVE_STRIKE_R));
        STEP = modRegistry.build("step", EFXDodgeSkill::new, (SkillBuilder)EFXDodgeSkill.createEFXDodgeBuilder().setDefaultAnimations(ExtraAnimations.BIPED_STEP_FORWARD_ONEHAND, ExtraAnimations.BIPED_STEP_BACKWARD_ONEHAND, ExtraAnimations.BIPED_STEP_LEFT_ONEHAND, ExtraAnimations.BIPED_STEP_RIGHT_ONEHAND, ExtraAnimations.BIPED_STEP_BACK).addAnimationsForWeapon((WeaponCategory)CapabilityItem.WeaponCategories.FIST, (Style)CapabilityItem.Styles.ONE_HAND, AnimationsX.BIPED_STEP_FORWARD, AnimationsX.BIPED_STEP_BACKWARD, AnimationsX.BIPED_STEP_LEFT, AnimationsX.BIPED_STEP_RIGHT));
        COMBAT_MASTERY_I = modRegistry.build("combat_mastery_i", CombatMastery_I::new, (SkillBuilder)CombatMastery_I.createCombatMasteryPassiveBuilder());
        COMBAT_MASTERY_II = modRegistry.build("combat_mastery_ii", CombatMastery_II::new, (SkillBuilder)CombatMastery_II.createCombatMasteryPassiveBuilder());
        PICKAXE_SKILL = modRegistry.build("pickaxe_skill", PickaxeSkill::new, (SkillBuilder)PickaxeSkill.createEFXWeaponInnateBuilder());
        SCYTHE_SKILL = modRegistry.build("scythe_skill", ScytheSkill::new, (SkillBuilder)ScytheSkill.createEFXWeaponInnateBuilder());
        GREATSWORD_DAGGER_SKILL = modRegistry.build("greatsworddagger_skill", GreatSwordDaggerSkill::new, (SkillBuilder)GreatSwordDaggerSkill.createEFXWeaponInnateBuilder());
        GREAT_TACHI_SKILL = modRegistry.build("otachi_skill", GreatTachiSkill::new, (SkillBuilder)GreatTachiSkill.createEFXWeaponInnateBuilder());
        KATANA_SKILL = modRegistry.build("katana_skill", KatanaInnate::new, (SkillBuilder)KatanaInnate.createEFXWeaponInnateBuilder());
        KATANA_PASSIVE_SKILL = modRegistry.build("katana_passive_skill", KatanaPassive::new, KatanaPassive.createPassiveBuilder().setCategory((SkillCategory)SkillCategories.WEAPON_PASSIVE).setResource(Skill.Resource.NONE));
    }
}

