    CapabilityItem holdingItem = executor.getHoldingItemCapability(InteractionHand.MAIN_HAND);
    WeaponCategory weaponCategory = holdingItem.getWeaponCategory();
    Style style = holdingItem.getStyle((LivingEntityPatch)executor);
    boolean isAttacking = (Boolean)dataManager.getDataValue((SkillDataKey)EFXSkillDataKeys.DODGE_ATTACKING.get());
    AnimationManager.AnimationAccessor<? extends StaticAnimation> animation = this.getAnimationForWeapon(weaponCategory, style, direction, isAttacking);
    if (animation != null) {
        executor.playAnimationSynchronized(animation, 0.0f);
        dataManager.setDataSync((SkillDataKey)EFXSkillDataKeys.DODGE_ATTACKING.get(), (Object)false);
        executor.setModelYRot(yRot, true);
    }
}

